let active='all',selected=0;const list=document.querySelector('#assetList'),detail=document.querySelector('#detail');
function render(){const filtered=assets.filter(a=>active==='all'||a.horizon===active);if(!filtered.includes(assets[selected]))selected=assets.indexOf(filtered[0]);list.innerHTML=filtered.map(a=>`<article class="asset ${assets.indexOf(a)===selected?'selected':''}" data-i="${assets.indexOf(a)}"><span class="ticker">${a.ticker}</span><div class="name"><b>${a.name}</b><small>${a.sector}</small></div><span class="reason">${a.reason}</span><span class="horizon ${a.horizon}">${a.label}</span><span class="score"><b>${a.score}</b><small>/ 100</small></span><span class="arrow">›</span></article>`).join('');document.querySelectorAll('.asset').forEach(el=>el.onclick=()=>{selected=+el.dataset.i;render()});const a=assets[selected];detail.innerHTML=`<div class="detail-top"><div><p class="eyebrow">THÈSE FONDAMENTALE</p><span class="pill">${a.label}</span></div><div class="big-score">${a.score}<small>/100</small></div></div><h2>${a.name} <span style="color:var(--muted);font:13px 'DM Mono'">${a.ticker}</span></h2><p>${a.price} <span style="color:${a.change.includes('−')?'var(--red)':'var(--mint)'}">${a.change}</span> · données de démonstration</p><div class="thesis"><b>Pourquoi le suivre :</b><br>${a.thesis}</div><div class="metrics">${a.metrics.map(m=>`<div class="metric"><small>${m[0]}</small><b>${m[1]}</b></div>`).join('')}</div><div class="sources">${a.sources.map(s=>`<a href="${s[1]}" target="_blank" rel="noreferrer">${s[0]} ↗</a>`).join('')}</div>`}render();
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{active=b.dataset.filter;document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render()});const dialog=document.querySelector('#methodDialog');document.querySelector('#methodBtn').onclick=()=>dialog.showModal();document.querySelector('#closeDialog').onclick=()=>dialog.close();
